199.       setSelectedOptionIndex(index);
200.       const option = safeOptions[index];
201.       setSearchValue(option.value || "");
202.       setFocusedIndex(safeOptions.findIndex((op) => op.key === option.key));
203.       setOpen(false);
204.       inputRef.current?.focus();
205. 
206.       // Only call onSearch if there's a value to search
207.       if (option.value) {
208.         onSearch(option.key, option.value);
209.       }
210.       onFieldChange?.(safeOptions[index]);
211.     },
212.     [onSearch, safeOptions, onFieldChange],
213.   );
