254.         } else if (e.key === "ArrowUp") {
255.           setFocusedIndex((prevIndex) =>
256.             prevIndex === 0 ? unselectedOptions.length - 1 : prevIndex - 1,
257.           );
258.         } else if (e.key === "Enter") {
