import { useQueryParams } from "raviger";
import { useCallback, useMemo } from "react";

interface UsePaginationOptions {
  /** Rows per page. Defaults to 15. */
  limit?: number;
  /** Query param name holding the 1-based page number. Defaults to "page". */
  paramName?: string;
}

/**
 * Minimal, self-contained replacement for care_fe's `useFilters`.
 *
 * A plug cannot import the host's hook (module federation only shares
 * `react`, `react-dom`, `react-i18next`, `@tanstack/react-query` and
 * `raviger`), and `useFilters` pulls in far more than pagination.
 * This keeps only the page/limit/offset arithmetic, backed by the URL so
 * the page survives a reload and back/forward navigation.
 */
export default function usePagination({
  limit = 15,
  paramName = "page",
}: UsePaginationOptions = {}) {
  const [qParams, setQueryParams] = useQueryParams<Record<string, string>>();

  const page = useMemo(() => {
    const parsed = Number(qParams[paramName]);
    return Number.isFinite(parsed) && parsed >= 1 ? Math.floor(parsed) : 1;
  }, [qParams, paramName]);

  const setPage = useCallback(
    (nextPage: number) => {
      setQueryParams(
        { ...qParams, [paramName]: String(Math.max(1, nextPage)) },
        { replace: false },
      );
    },
    [qParams, setQueryParams, paramName],
  );

  return {
    page,
    limit,
    offset: (page - 1) * limit,
    setPage,
  };
}

import { useTranslation } from "react-i18next";

import { cn } from "@/lib/utils";

import CareIcon from "@/CAREUI/icons/CareIcon";

import { Button } from "@/components/ui/button";

interface PaginationProps {
  page: number;
  limit: number;
  totalCount: number;
  onPageChange: (page: number) => void;
  className?: string;
}

/**
 * Minimal pagination footer for the plug. Renders nothing when everything
 * fits on a single page.
 */
export default function Pagination({
  page,
  limit,
  totalCount,
  onPageChange,
  className,
}: PaginationProps) {
  const { t } = useTranslation();
  const totalPages = Math.ceil(totalCount / limit);

  if (!totalCount || totalPages <= 1) {
    return null;
  }

  const from = (page - 1) * limit + 1;
  const to = Math.min(page * limit, totalCount);

  return (
    <nav
      aria-label={t("pagination")}
      className={cn(
        "flex items-center justify-center gap-4 py-2",
        className,
      )}
    >
      <Button
        variant="outline"
        size="sm"
        disabled={page <= 1}
        onClick={() => onPageChange(page - 1)}
        aria-label={t("prev")}
      >
        <CareIcon icon="l-angle-left" className="size-4" />
      </Button>

      <span aria-live="polite" className="text-sm text-gray-600">
        {from}&ndash;{to} / {totalCount}
      </span>

      <Button
        variant="outline"
        size="sm"
        disabled={page >= totalPages}
        onClick={() => onPageChange(page + 1)}
        aria-label={t("next")}
      >
        <CareIcon icon="l-angle-right" className="size-4" />
      </Button>
    </nav>
  );
}

